    "Boosts of other people" : "Muiden ihmisten tehostuksia",
    "Counted over your {count} most recent posts, which is as far back as this page goes." : "Laskettu {count} uusimpien viestiesi yli, mikä on tältä sivulta pitkältä ajalta.",
    "_Counted over your one post._::_Counted over all {count} of your posts._" : ["Laskettu yhteen viestiisi.", "Laskettu kaikkiin {count} viestiisi."],
    "Could not work out your statistics." : "Tilastojasi ei voitu selvittää.",
    "new" : "uusi",
    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n sitoutumista {month}", "%n sitoutumista {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n seuraajaa kohteessa {month}", "%n seuraajaa kohteessa {month}"],
